/** What remains of the total the office will pay out over this policy's life. */
public int remainingCap() {
    return remainingCap;
}

/**
 * The office draws a settled payout against the policy's cap, and the policy
 * reports what is left of it. The cap is the policy's own ledger: only the policy
 * knows how much of it earlier claims have already spent.
 */
int drawAgainstCap(int payout) {
    remainingCap -= payout;
    return remainingCap;
}

